import{z as A,x as i,o as s,c as t,q as e,j as r,D as E,d as o,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"沙箱逃逸","description":"","frontmatter":{"title":"沙箱逃逸","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-sandbox-escape.md","filePath":"cs/ss-sandbox-escape.md","lastUpdated":1791413859000}'),c={name:"cs/ss-sandbox-escape.md"};function d(p,a,h,C,m,u){const B=i("Mermaid");return s(),t("div",null,[a[2]||(a[2]=e('<h1 id="沙箱逃逸" tabindex="-1">沙箱逃逸 <a class="header-anchor" href="#沙箱逃逸" aria-label="Permalink to &quot;沙箱逃逸&quot;">​</a></h1><div class="epigraph"><p>沙箱从不承诺攻击者进不来，它承诺的是：进得来的那份代码，能摸到的世界已经小得可怜；逃逸研究的正是这份「小」在哪里失守。</p><footer>—— 据 Barth, Jackson and Reis, The Security Architecture of the Chromium Browser, 2008；Linux seccomp(2) 整理</footer></div><p><a href="/cs/ss-kernel-vuln-classes">上一课</a>把内核漏洞钉成两条轴：根因给原语，原语给提权，并留下一句「沙箱管剩余爆炸半径」。本课就把这句话展开。主干已有<a href="/cs/isolation-sandbox">隔离与沙箱</a>、<a href="/cs/browser-sandbox">浏览器沙箱</a>、<a href="/cs/seccomp-filter">seccomp 过滤器</a>、<a href="/cs/container-escape">容器逃逸</a>与<a href="/cs/vm-escape">虚拟机逃逸</a>；缺口是把「逃逸」本身当成一个类别来写：边界由谁执行，执行者的哪几类失败会把它变成纸。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>沙箱的承诺靠一条组件链兑现：格内进程 → 内核的过滤器与命名空间 → CPU 特权级。承诺因此与链上最弱的一环同命。逃逸不是一类 bug，而是这条链上的三种失败。其一，执行者之下的漏洞：所有格子共享同一面内核墙，<a href="/cs/ss-kernel-vuln-classes">上一课类别表</a>里的任何一格，落到边界执行者头上就是逃逸。其二，合法通道的滥用：格子必须留出口——渲染器要网络、要文件句柄——高权的中间人替格内代码办事时，一个混淆代理人 bug 就把出口变成了洞。其三，策略误配：能力默认没收、通道显式开，这条纪律反过来就是默认全开、事后修补。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="缩面、窄通道与误配审计" tabindex="-1">缩面、窄通道与误配审计 <a class="header-anchor" href="#缩面、窄通道与误配审计" aria-label="Permalink to &quot;缩面、窄通道与误配审计&quot;">​</a></h3><p>三招对应三种失败。缩面：syscall 过滤器把内核入口从几百个砍到几十个——类别表里凡是入口在 syscall 的根因，先在门口折损一截；Windows 侧同理，win32k 锁定把历史悠久的图形子系统从浏览器可达面里裁掉。窄通道：进程间只传句柄与强校验的结构化消息，反序列化是新的检查点；站点隔离再把不同站点的渲染器分格，让一个格子的代码执行不再等于跨站读。误配审计：通道清单进版本库，默认拒绝写进模板而非记忆。</p>',8)),(s(),r(n,null,{default:E(()=>[l(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUG%5B%22%E6%A0%BC%E5%86%85%E6%BC%8F%E6%B4%9E%EF%BC%9A%E6%B8%B2%E6%9F%93%E5%99%A8%20RCE%20%2F%20%E6%9C%8D%E5%8A%A1%20RCE%22%5D%20--%3E%20P1%5B%22%E5%8F%AF%E8%BE%BE%E9%9D%A2%EF%BC%9A%E8%BF%87%E6%BB%A4%E5%90%8E%E7%9A%84%20syscall%20%E5%AD%90%E9%9B%86%22%5D%0A%20%20P1%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%EF%BC%9A%E6%89%80%E6%9C%89%E6%A0%BC%E5%AD%90%E5%85%B1%E7%94%A8%E7%9A%84%E5%A2%99%22%5D%0A%20%20BUG%20--%3E%20IPC%5B%22%E5%90%88%E6%B3%95%E9%80%9A%E9%81%93%EF%BC%9AIPC%20%2F%20%E5%8F%A5%E6%9F%84%E4%BC%A0%E9%80%92%22%5D%0A%20%20IPC%20--%3E%20DEP%5B%22%E6%B7%B7%E6%B7%86%E4%BB%A3%E7%90%86%E4%BA%BA%EF%BC%9A%E9%AB%98%E6%9D%83%E8%BF%9B%E7%A8%8B%E4%BB%A3%E5%8A%9E%22%5D%0A%20%20DEP%20--%3E%20K%0A%20%20MIS%5B%22%E7%AD%96%E7%95%A5%E8%AF%AF%E9%85%8D%EF%BC%9A%E9%BB%98%E8%AE%A4%E6%B2%A1%E6%94%B6%E5%A4%B1%E6%95%88%22%5D%20--%3E%20OUT%5B%22%E6%A0%BC%E5%A4%96%E7%9A%84%E4%B8%96%E7%95%8C%22%5D%0A%20%20K%20--%3E%20OUT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">Chromium 与 Adobe Reader 在 Windows 上启用 win32k 锁定：进程被禁止调用 win32k 系统调用，图形子系统那部分内核面从格内不可达。据 Microsoft 进程缓解策略文档与 Chromium 文档整理。</span></p><p><span class="marginnote">「混淆代理人」翻译成大白话：一个手握权限的老实人，被外人骗着用自己的权限办了外人的私事。比如高权的浏览器主进程替渲染器去读文件，渲染器递过去的「文件名」其实是个设备路径——代办进程按自己的高权限执行了，账却记在格内代码头上。防御思路因此是让代办只收强校验的结构化消息，不收裸字符串。</span></p><p><span class="marginnote">缩面的数字直觉：Linux 的 syscall 入口有三百多个，seccomp 白名单过后通常只剩几十个——可达面直接折损一个数量级。类别表里凡是「入口在 syscall」的空间、整数类漏洞，其中九成都因为对应入口被关掉而先在门口撞墙；剩下进得来的入口，才是攻击者真正能研究的面。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>关键机制判断是：沙箱不修内核漏洞。格内与格外跑在同一个内核上，<a href="/cs/ss-kernel-vuln-classes">内核漏洞类别</a>那张表对格内攻击者照样成立；沙箱改变的是可达性——够得着的 syscall、文件与设备变少，同一条利用链的工程代价变高。逃逸的度量因此是「从格内 bug 到原语的距离」：窄 IPC 加站点隔离把这条路从「渲染器 RCE 直达内核」逼成「还要再找一个 IPC 逻辑 bug」，攻击成本抬一个量级，逃逸就从批量转为定向。容器与虚拟机的对照在此对齐：共享内核的容器，边界执行者就是内核本身；虚拟机多一层管理程序，设备模拟器成为高危 TCB——两课已有专述，此处只借它们的结论对表。</p>',5)),(s(),r(n,null,{default:E(()=>[l(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PROC%5B%22%E6%A0%BC%E5%86%85%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20CONT%5B%22%E5%AE%B9%E5%99%A8%EF%BC%9A%E5%86%85%E6%A0%B8%E5%8D%B3%E8%BE%B9%E7%95%8C%E6%89%A7%E8%A1%8C%E8%80%85%22%5D%0A%20%20PROC%20--%3E%20VMM%5B%22%E8%99%9A%E6%8B%9F%E6%9C%BA%EF%BC%9Ahypervisor%20%E4%B8%BA%E8%BE%B9%E7%95%8C%22%5D%0A%20%20CONT%20--%3E%20KERN%5B%22%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%EF%BC%9A%E5%86%85%E6%A0%B8%E6%BC%8F%E6%B4%9E%E5%8D%B3%E9%80%83%E9%80%B8%22%5D%0A%20%20VMM%20--%3E%20HV%5B%22hypervisor%20%E4%B8%8E%E8%AE%BE%E5%A4%87%E6%A8%A1%E6%8B%9F%E6%88%90%E4%B8%BA%20TCB%22%5D%0A%20%20KERN%20--%3E%20THIN%5B%22%E5%A2%99%E8%96%84%EF%BC%9A%E9%80%83%E9%80%B8%E4%BB%A3%E4%BB%B7%E4%BD%8E%22%5D%0A%20%20HV%20--%3E%20THICK%5B%22%E5%A2%99%E5%8E%9A%EF%BC%9A%E9%80%83%E9%80%B8%E4%BB%A3%E4%BB%B7%E9%AB%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">初学者容易以为「沙箱挡住了漏洞」，实际上沙箱一个漏洞都没修——它只是把攻击者从「面前是无锁的大门」改成「面前是一条要绕三道的窄走廊」。度量这条走廊的长度，正是本课说的「从格内 bug 到原语的距离」：走廊越长，批量攻击越不划算，攻击者就越只能挑高价值目标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>容器逃逸与虚拟机逃逸的机制细节主干已有专课，本课不重讲；侧信道能把数据从格子漏出去但不破坏 confinement 的完整性，按隔离课「微结构泄漏另计」的口径处理；具体 CVE 的利用步骤不写。格子的策略语言如何表达最小权限，属于各平台模型——移动一课会回到这个话题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逃逸是承诺链上的三种失败：执行者之下的内核漏洞、合法通道的混淆代理、策略误配。</li><li>对应三招：syscall 缩面、窄通道与强校验 IPC、默认没收加审计。</li><li>沙箱不修内核漏洞，只改可达性；度量是「从格内 bug 到原语的距离」。</li><li>站点隔离把「一次 RCE」与「跨站」解耦，逃逸成本抬升后批量转为定向。</li><li>出处：Barth, Jackson and Reis, 2008；seccomp(2)；对照 <a href="/cs/browser-sandbox">browser-sandbox</a>、<a href="/cs/isolation-sandbox">isolation-sandbox</a>。</li></ul>',5))])}const b=A(c,[["render",d]]);export{f as __pageData,b as default};
